package org.codex.nfsugpreview;
import android.app.*;import android.content.*;import android.os.*;import android.opengl.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public final class LivePresentationInstrumentation extends Instrumentation {
 interface Condition{boolean ready();}
 void ok(boolean b,String why){if(!b)throw new AssertionError(why);}
 void until(Condition c,String reason,LiveTestActivity a)throws Exception{long deadline=System.nanoTime()+45000000000L;while(!c.ready()){if(System.nanoTime()>deadline)throw new AssertionError(reason+" status="+a.status+" native="+a.view.nativeFramesRendered+" original="+a.view.originalFramesRendered+" enabled="+a.session.nativeDisplayEnabled()+" attempts="+a.session.nativePresentationAttempts+" complete="+a.session.nativeCompleteScenes+" accepted="+a.session.nativePresentationAccepted);Thread.sleep(20);}}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();LiveTestActivity activity=null;try{
  String fixtureRoot="live-profile-"+UUID.randomUUID();LiveTestActivity.TEST_ROOT=fixtureRoot;File files=getTargetContext().getFilesDir(),root=new File(files,fixtureRoot);ok(root.mkdir(),"Unique test directory must not already exist");Files.copy(new File(files,"background-test.gba").toPath(),new File(root,"game.gba").toPath());Files.copy(new File(files,"background-test.state").toPath(),new File(root,"resume.state").toPath());
  Intent intent=new Intent(getTargetContext(),LiveTestActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(LiveTestActivity)startActivitySync(intent);final LiveTestActivity a=activity;
  until(()->a.view.nativeFramesRendered>=3,"No native display",a);NativePresentation.Frame first=a.session.presentation.latest();ok(first!=null&&first.scene!=null,"Complete moving scene");long refresh=first.refresh;until(()->{NativePresentation.Frame p=a.session.presentation.latest();return p!=null&&p.scene!=null&&p.refresh>refresh+3;},"No moving native publication",a);
  CountDownLatch image=new CountDownLatch(1);AtomicReference<Throwable> imageFailure=new AtomicReference<>();AtomicInteger samples=new AtomicInteger();
  a.view.probe=(frame,x,y,w,h)->{if(frame==null)return;a.view.probe=null;try{ByteBuffer screen=ByteBuffer.allocateDirect(w*h*4);GLES20.glReadPixels(x,y,w,h,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,screen);ok(GLES20.glGetError()==GLES20.GL_NO_ERROR,"Screen read");int[] names={0};GLES20.glGenTextures(1,names,0);int texture=names[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,texture);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,w,h,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,names,0);int fbo=names[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,texture,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"Reference FBO");try(NativeBackgroundSceneGpu reference=new NativeBackgroundSceneGpu()){reference.drawRetained(frame.scene,w,h,w,h);ByteBuffer expected=ByteBuffer.allocateDirect(w*h*4);GLES20.glReadPixels(0,0,w,h,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,expected);for(int at=0;at<w*h*4;at++)ok(screen.get(at)==expected.get(at),"Live framebuffer orientation/blit pixel "+at);samples.set(w*h);}finally{GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{texture},0);}}catch(Throwable failure){imageFailure.set(failure);}finally{image.countDown();}};
  ok(image.await(60,TimeUnit.SECONDS),"Image probe timeout");if(imageFailure.get()!=null)throw new AssertionError(imageFailure.get());ok(samples.get()>38400,"Display resolution");
  runOnMainSync(()->a.session.active(false));ok(a.session.presentation.latest()==null,"Pause stale mailbox");Thread.sleep(300);ok(a.session.presentation.latest()==null,"Paused producer republished");runOnMainSync(()->a.session.active(true));until(()->a.session.presentation.latest()!=null&&a.session.presentation.latest().scene!=null,"Resume source",a);
  runOnMainSync(()->a.session.nativeDisplay(false));ok(a.session.presentation.latest()==null,"Mode stale mailbox");long fallback=a.view.originalFramesRendered;until(()->a.view.originalFramesRendered>fallback+2,"Original fallback",a);runOnMainSync(()->a.session.nativeDisplay(true));final long before=a.view.nativeFramesRendered;until(()->a.view.nativeFramesRendered>before+2,"Native mode restart",a);
  runOnMainSync(()->{a.session.active(false);a.view.onPause();});ok(a.session.presentation.latest()==null,"Context pause stale");runOnMainSync(()->{a.view.onResume();a.session.active(true);});final long contextBefore=a.view.nativeFramesRendered;until(()->a.view.nativeFramesRendered>contextBefore+2,"Context recreate native",a);
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_LIVE_PRESENTATION");report.put("isolated_fixture_root",fixtureRoot);ok(a.session.nativeLegacySceneCopiesAvoided>0&&a.session.nativeSceneAliases>0,"Complete scene not shared");report.put("legacy_scene_copies_avoided",a.session.nativeLegacySceneCopiesAvoided);report.put("complete_scene_aliases",a.session.nativeSceneAliases);report.put("native_frames",a.view.nativeFramesRendered);report.put("unique_native_frames",a.view.uniqueNativeFramesRendered);long[][] completedProfile=a.session.profile.snapshot();report.put("capture_profile_completed_work",true);JSONObject profile=new JSONObject();for(int stage=0;stage<NativeWorkProfile.NAMES.length;stage++){long[] metric=completedProfile[stage];JSONObject row=new JSONObject();row.put("calls",metric[0]);row.put("total_ms",metric[1]/1000000.0);row.put("max_ms",metric[2]/1000000.0);row.put("mean_ms",metric[0]==0?0:metric[1]/1000000.0/metric[0]);profile.put(NativeWorkProfile.NAMES[stage],row);}report.put("profile_cpu_dispatch",profile);report.put("original_frames",a.view.originalFramesRendered);report.put("superseded_valid_frames",a.view.supersededFramesRendered);report.put("screen_reference_pixels",samples.get());report.put("moving_refreshes",true);report.put("pause_resume",true);report.put("mode_fallback_restart",true);report.put("context_recreated",true);report.put("real_time_pacing_verified",false);report.put("full_scene_60fps",false);report.put("status",a.status);try(FileOutputStream out=getTargetContext().openFileOutput("live-presentation-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){android.util.Log.e("NFSUGLiveTest","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}finally{if(activity!=null){final LiveTestActivity a=activity;runOnMainSync(()->a.finish());}}}
}

